func (v DetailsValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributeTypes := map[string]attr.Type{
		"drain_time":           basetypes.StringType{},
		"error":                basetypes.StringType{},
		"node_name":            basetypes.StringType{},
		"reboot_recovery_time": basetypes.StringType{},
		"reboot_time":          basetypes.StringType{},
		"success":              basetypes.BoolType{},
		"undrain_time":         basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"drain_time":           v.DrainTime,
			"error":                v.Error,
			"node_name":            v.NodeName,
			"reboot_recovery_time": v.RebootRecoveryTime,
			"reboot_time":          v.RebootTime,
			"success":              v.Success,
			"undrain_time":         v.UndrainTime,
		})

	return objVal, diags
}

func (v DetailsValue) Equal(o attr.Value) bool {
	other, ok := o.(DetailsValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.DrainTime.Equal(other.DrainTime) {
		return false
	}

	if !v.Error.Equal(other.Error) {
		return false
	}

	if !v.NodeName.Equal(other.NodeName) {
		return false
	}

	if !v.RebootRecoveryTime.Equal(other.RebootRecoveryTime) {
		return false
	}

	if !v.RebootTime.Equal(other.RebootTime) {
		return false
	}

	if !v.Success.Equal(other.Success) {
		return false
	}

	if !v.UndrainTime.Equal(other.UndrainTime) {
		return false
	}

	return true
}

